<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');
$campaignId=(int)($_GET['campaign_id']??$_POST['campaign_id']??0);$campaigns=pg_query($conn,'SELECT id,title,status FROM feedback_campaigns ORDER BY created_at DESC');$campaign=null;if($campaignId){$r=pg_query_params($conn,'SELECT * FROM feedback_campaigns WHERE id=$1',[$campaignId]);$campaign=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$campaign){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$prompt=trim($_POST['prompt']??'');$type=$_POST['question_type']??'text';$types=['rating','single_choice','multiple_choice','text'];$lines=preg_split('/\R/',trim($_POST['options']??''));$options=array_values(array_filter(array_map('trim',$lines)));if($prompt==='')$error='Question text is required.';elseif(!in_array($type,$types,true))$error='Invalid question type.';elseif(in_array($type,['single_choice','multiple_choice'],true)&&count($options)<2)$error='Choice questions need at least two options.';else{$order=(int)($_POST['display_order']??0);$required=isset($_POST['is_required'])?'true':'false';$json=json_encode($options);$ok=$id?pg_query_params($conn,'UPDATE feedback_questions SET prompt=$1,question_type=$2,options=$3::jsonb,is_required=$4,display_order=$5 WHERE id=$6 AND campaign_id=$7',[$prompt,$type,$json,$required,$order,$id,$campaignId]):pg_query_params($conn,'INSERT INTO feedback_questions(campaign_id,prompt,question_type,options,is_required,display_order) VALUES($1,$2,$3,$4::jsonb,$5,$6)',[$campaignId,$prompt,$type,$json,$required,$order]);if($ok)redirect('index.php?campaign_id='.$campaignId.'&saved=1');else$error='Question could not be saved.';}}elseif($action==='delete'&&$id){$used=pg_query_params($conn,'SELECT COUNT(*) FROM feedback_answers WHERE question_id=$1',[$id]);if($used&&(int)pg_fetch_result($used,0,0)>0)$error='A question with recorded answers cannot be deleted.';else{pg_query_params($conn,'DELETE FROM feedback_questions WHERE id=$1 AND campaign_id=$2',[$id,$campaignId]);redirect('index.php?campaign_id='.$campaignId);}}}}
$edit=null;$editId=(int)($_GET['edit']??0);if($editId&&$campaign){$r=pg_query_params($conn,'SELECT * FROM feedback_questions WHERE id=$1 AND campaign_id=$2',[$editId,$campaignId]);$edit=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}$questions=$campaign?pg_query_params($conn,'SELECT * FROM feedback_questions WHERE campaign_id=$1 ORDER BY display_order,id',[$campaignId]):null;admin_page_start('Questions','questions');?>
<div class="hero"><div><h2>Question builder</h2><p>Combine ratings, choices, and open comments into a focused questionnaire.</p></div></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="card"><form method="get" class="form-grid"><div class="field full"><label>Campaign</label><select name="campaign_id" onchange="this.form.submit()"><option value="">Choose a campaign…</option><?php if($campaigns):while($c=pg_fetch_assoc($campaigns)):?><option value="<?=(int)$c['id']?>" <?=$campaignId===(int)$c['id']?'selected':''?>><?=h($c['title'])?> (<?=h($c['status'])?>)</option><?php endwhile;endif;?></select></div></form></div>
<?php if($campaign):$v=$edit?:[];?><div class="card"><h3><?=$edit?'Edit question':'Add a question'?></h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="campaign_id" value="<?=$campaignId?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><div class="field full"><label>Question</label><input name="prompt" required value="<?=h($v['prompt']??'')?>"></div><div class="field"><label>Answer type</label><select name="question_type" id="questionType" onchange="toggleOptions()"><?php foreach(['rating'=>'Rating (1–5)','single_choice'=>'Single choice','multiple_choice'=>'Multiple choice','text'=>'Written response'] as $key=>$label):?><option value="<?=$key?>" <?=($v['question_type']??'rating')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label>Display order</label><input type="number" min="0" name="display_order" value="<?=h($v['display_order']??(($questions?pg_num_rows($questions):0)+1))?>"></div><div class="field full" id="optionsField"><label>Options (one per line)</label><textarea name="options"><?php $opts=json_decode($v['options']??'[]',true)?:[];echo h(implode("\n",$opts));?></textarea></div><div class="field full"><label class="choice"><input type="checkbox" name="is_required" <?=($v['is_required']??'t')==='t'?'checked':''?>> Required question</label></div><div class="field full actions"><button class="btn">Save question</button><?php if($edit):?><a class="btn secondary" href="?campaign_id=<?=$campaignId?>">Cancel</a><?php endif;?></div></form></div>
<div class="card"><h3><?=h($campaign['title'])?> · Questions</h3><div class="table-wrap"><table><thead><tr><th>Order</th><th>Question</th><th>Type</th><th>Required</th><th>Actions</th></tr></thead><tbody><?php if($questions):while($q=pg_fetch_assoc($questions)):?><tr><td><?=(int)$q['display_order']?></td><td><strong><?=h($q['prompt'])?></strong><?php $o=json_decode($q['options'],true)?:[];if($o):?><div class="help"><?=h(implode(' · ',$o))?></div><?php endif;?></td><td><span class="badge"><?=h(str_replace('_',' ',ucfirst($q['question_type'])))?></span></td><td><?=$q['is_required']==='t'?'Yes':'No'?></td><td><div class="actions"><a class="btn small secondary" href="?campaign_id=<?=$campaignId?>&edit=<?=(int)$q['id']?>">Edit</a><form method="post" data-confirm-title="Delete question?" data-confirm="This question and its stored answers will be permanently deleted." data-confirm-button="Yes, delete it"><?=csrf_field()?><input type="hidden" name="campaign_id" value="<?=$campaignId?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$q['id']?>"><button class="btn small danger">Delete</button></form></div></td></tr><?php endwhile;endif;if(!$questions||pg_num_rows($questions)===0):?><tr><td colspan="5" class="empty">No questions yet.</td></tr><?php endif;?></tbody></table></div></div><script>function toggleOptions(){const t=document.getElementById('questionType').value;document.getElementById('optionsField').style.display=['single_choice','multiple_choice'].includes(t)?'grid':'none'}toggleOptions()</script><?php endif;admin_page_end();?>
